            const savedRef = String(saved && (saved.photoPublicId || saved.photoRef || saved.profilePhotoRef || saved.profileImageRef || saved.avatarRef || saved.publicId || saved.ref) || "").trim();
            if (!savedPhoto && !savedRef) throw new Error("Profile image was not saved to shared storage.");
