          const cards = Array.from(document.querySelectorAll("[data-search-text]"));
          const activeReelTab = document.querySelector("[data-reel-tab].is-active");
          const activeReelKind = homeNormalizeReelKind(activeReelTab ? activeReelTab.dataset.reelTab : "business");
          let visible = 0;
          cards.forEach((card) => {
            const match = !normalized || (card.dataset.searchText || "").toLowerCase().includes(normalized);
            const reelMatch = !card.dataset.reelKind || homeNormalizeReelKind(card.dataset.reelKind) === activeReelKind;
            card.hidden = !(match && reelMatch);
            if (match && reelMatch && !card.closest("[hidden]")) visible += 1;
          });
          empty.classList.toggle("is-visible", !!normalized && visible === 0);
          syncHomeCarouselSections();
